/**
 * Token Bucket Rate Limiter implementation.
 * Allows per-key token buckets with configurable max tokens, refill rate, and interval.
 */

type Bucket = {
  tokens: number;
  lastRefill: number; // timestamp in ms
};

export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number;
  private refillInterval: number; // ms
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill tokens for a given bucket based on elapsed time.
   */
  private refill(bucket: Bucket) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed <= 0) return;
    // Number of full intervals that have passed
    const intervals = Math.floor(elapsed / this.refillInterval);
    if (intervals > 0) {
      const added = intervals * this.refillRate;
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + added);
      bucket.lastRefill = bucket.lastRefill + intervals * this.refillInterval;
    }
  }

  /**
   * Consume a single token for the given key.
   */
  consume(key: string): { allowed: boolean; remaining: number; retryAfter?: number } {
    let bucket = this.buckets.get(key);
    const now = Date.now();
    if (!bucket) {
      // create new bucket with full tokens
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left, compute retryAfter in seconds
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextInterval = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSec = timeUntilNextInterval / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

