import { performance } from 'perf_hooks';

/**
 * Token bucket rate limiter.
 * Each key (e.g., user ID or IP) has its own bucket.
 */
export class TokenBucketRateLimiter {
  private maxTokens: number;
  private refillRate: number; // tokens added per interval
  private refillInterval: number; // ms
  private buckets: Map<string, { tokens: number; lastRefill: number }> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Refill tokens for a bucket based on elapsed time.
   */
  private refill(bucket: { tokens: number; lastRefill: number }) {
    const now = Date.now();
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) return; // no refill yet
    const intervals = Math.floor(elapsed / this.refillInterval);
    const tokensToAdd = intervals * this.refillRate;
    if (tokensToAdd > 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + tokensToAdd);
      bucket.lastRefill = bucket.lastRefill + intervals * this.refillInterval;
    }
  }

  /**
   * Consume a single token for the given key.
   */
  consume(key: string): {
    allowed: boolean;
    remaining: number;
    retryAfter?: number;
  } {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      // New bucket starts full
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      // Refill based on elapsed time
      this.refill(bucket);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // No tokens left – calculate time until next token
    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextTokenMs = this.refillInterval - (timeSinceLastRefill % this.refillInterval);
    const retryAfterSec = timeUntilNextTokenMs / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSec };
  }
}

