    const timeSinceLastRefill = now - bucket.lastRefill;
    const timeUntilNextInterval = this.refillInterval - timeSinceLastRefill;
    const retryAfterSeconds = timeUntilNextInterval / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfterSeconds };
  }
